+        linear-gradient(180deg, #020617 0%, var(--bg) 45%, #111827 100%);
+      color: var(--text);
+      display: grid;
+      place-items: center;
+      padding: 32px 16px;
+    }
+
+    .page {
+      width: min(860px, 100%);
