+      border: 1px solid var(--panel-border);
+      border-radius: 24px;
+      box-shadow: var(--shadow);
+      padding: 32px;
+      backdrop-filter: blur(16px);
+    }
+
+    .eyebrow {
+      margin: 0 0 10px;
+      color: var(--accent);
+      font-size: 0.85rem;
+      font-weight: 700;
+      letter-spacing: 0.12em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2rem, 4vw, 3.25rem);
+      line-height: 1.05;
+    }
+
+    .intro {
+      margin: 14px 0 0;
+      max-width: 62ch;
+      color: var(--muted);
+      font-size: 1.02rem;
+      line-height: 1.7;
+    }
+
+    .faq-list {
+      margin-top: 28px;
+      display: grid;
+      gap: 14px;
+    }
+
+    .example {
+      border: 1px solid rgba(125, 211, 252, 0.14);
+      background: rgba(15, 23, 42, 0.86);
+      border-radius: 18px;
+      overflow: clip;
+      transition: border-color 160ms ease, transform 160ms ease, background 160ms ease;
+    }
+
+    .example:hover {
+      border-color: rgba(125, 211, 252, 0.28);
+      transform: translateY(-1px);
+      background: rgba(15, 23, 42, 0.96);
+    }
+
+    .question {
+      width: 100%;
+      border: 0;
+      margin: 0;
+      padding: 18px 20px;
+      background: transparent;
+      color: var(--text);
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 20px;
+      font: inherit;
+      font-size: 1.02rem;
+      font-weight: 650;
+      text-align: left;
+      cursor: pointer;
+    }
+
+    .question:focus-visible {
+      outline: 2px solid var(--accent-strong);
+      outline-offset: -2px;
+    }
+
+    .chevron {
+      flex: none;
+      width: 1rem;
+      height: 1rem;
+      border-right: 2px solid var(--accent);
+      border-bottom: 2px solid var(--accent);
+      transform: rotate(45deg);
+      transition: transform 180ms ease;
+      margin-right: 4px;
+    }
+
+    .question[aria-expanded="true"] .chevron {
+      transform: rotate(225deg);
+      margin-top: 8px;
+    }
+
+    .details {
+      padding: 0 20px 20px;
+      color: #d5e3f7;
+      line-height: 1.75;
+    }
+
+    .details[hidden] {
+      display: none;
+    }
+
+    .details p {
+      margin: 0;
+    }
+
+    @media (max-width: 640px) {
+      .page {
+        padding: 24px 18px;
+        border-radius: 20px;
+      }
+
+      .question,
+      .details {
+        padding-left: 16px;
+        padding-right: 16px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <div id="app"></div>
+  <script>
+    const faqItems = [
+      {
+        question: "Why do cats purr?",
+        answer: "Cats often purr when they feel relaxed and content, but purring can also be a way to self-soothe when they are stressed, injured, or seeking comfort from people they trust."
+      },
+      {
+        question: "How much sleep do cats need?",
+        answer: "Most cats sleep between 12 and 16 hours a day. Kittens, senior cats, and especially active breeds may rest even longer because short bursts of hunting-style energy take a lot out of them."
+      },
+      {
+        question: "Why do cats knead with their paws?",
+        answer: "Kneading starts in kittenhood to stimulate milk flow, and many adult cats keep the behavior because it feels safe and familiar. It is usually a sign that your cat feels secure in its environment."
+      },
+      {
+        question: "Do indoor cats still need enrichment?",
+        answer: "Yes. Indoor cats benefit from climbing spaces, scratching posts, puzzle feeders, window perches, and short interactive play sessions that let them stalk, chase, and pounce in healthy ways."
+      },
+      {
+        question: "Why do cats flick their tails?",
+        answer: "A tail flick can signal focus, excitement, irritation, or overstimulation depending on the rest of the cat's body language. Ears, posture, and vocal sounds give helpful extra context."
+      }
+    ];
+
+    function FAQItem({ question, answer, index }) {
+      const section = document.createElement("div");
+      const button = document.createElement("button");
+      const details = document.createElement("div");
+      const label = document.createElement("span");
+      const chevron = document.createElement("span");
+      const paragraph = document.createElement("p");
+
+      const detailsId = `faq-details-${index}`;
+
+      section.className = "example";
+
+      button.className = "question";
+      button.type = "button";
+      button.setAttribute("aria-expanded", "false");
+      button.setAttribute("aria-controls", detailsId);
+
+      label.textContent = question;
+
+      chevron.className = "chevron";
+      chevron.setAttribute("aria-hidden", "true");
+
+      button.append(label, chevron);
+
+      details.className = "details";
+      details.id = detailsId;
+      details.hidden = true;
+
+      paragraph.textContent = answer;
+      details.append(paragraph);
+
+      button.addEventListener("click", () => {
+        const isExpanded = button.getAttribute("aria-expanded") === "true";
+        button.setAttribute("aria-expanded", String(!isExpanded));
+        details.hidden = isExpanded;
+      });
+
+      section.append(button, details);
+      return section;
+    }
+
+    function FAQList({ items }) {
+      const list = document.createElement("div");
+      list.className = "faq-list";
+      items.forEach((item, index) => list.append(FAQItem({ ...item, index })));
+      return list;
+    }
+
+    function App() {
+      const page = document.createElement("main");
+      const eyebrow = document.createElement("p");
+      const title = document.createElement("h1");
+      const intro = document.createElement("p");
+
+      page.className = "page";
+
+      eyebrow.className = "eyebrow";
+      eyebrow.textContent = "Cat care essentials";
+
+      title.textContent = "Frequently asked questions about cats";
+
+      intro.className = "intro";
+      intro.textContent = "Explore quick answers to common questions about feline behavior, routines, and care. Each answer starts collapsed so the page stays tidy and easy to scan.";
+
+      page.append(eyebrow, title, intro, FAQList({ items: faqItems }));
+      return page;
+    }
+
+    document.getElementById("app").append(App());
+  </script>
+</body>
+</html>
*** End Patch
